import{z as o,x as l,o as s,c as d,q as A,j as n,D as a,d as t,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"无共享对共享存储","description":"","frontmatter":{"title":"无共享对共享存储","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shared-nothing-vs-disk.md","filePath":"cs/shared-nothing-vs-disk.md","lastUpdated":1791063341000}'),p={name:"cs/shared-nothing-vs-disk.md"};function h(D,E,C,c,m,f){const r=l("Mermaid");return s(),d("div",null,[E[2]||(E[2]=A('<h1 id="无共享对共享存储" tabindex="-1">无共享对共享存储 <a class="header-anchor" href="#无共享对共享存储" aria-label="Permalink to &quot;无共享对共享存储&quot;">​</a></h1><div class="epigraph"><p>无共享：每节点私有盘，扩展靠网络 shuffle。共享磁盘：多节点挂同一存储，扩展靠缓存一致性与锁，故障切换快。</p><footer>—— 据 DeWitt and Gray 并行库分类；Stonebraker shared-nothing；Oracle RAC 点名</footer></div><p><a href="/cs/db-consistent-hashing">上一课</a>在环上放键。本课不谈令牌。缺口是经典三分法里的两极（共享内存较少作今日主路径）：shared-nothing vs shared-disk。决定故障域、扩展曲线、以及下一课存算能否分离。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无共享：MPP、大多数 NewSQL、Postgres 单机+分片中间件。节点挂则其数据要副本才可服务。扩展加机器加盘。共享磁盘：多机可开同一库文件，缓存融合（cache fusion）传页，分布式锁管理器（DLM）代单机 latch+lock 的一部分。缺口是<strong>争用</strong>：共享盘上写同一页要跨机锁，热点差；无共享把热点变成单节点但扩展线性较好。</p><p>恢复：共享盘可把计算挂到另一机立刻看到盘（要锁与缓存重建）；无共享要副本升主。</p><p><span class="marginnote">DeWitt and Gray CACM 并行数据库。Stonebraker 主张 shared-nothing。RAC 是共享盘代表。本课分类，不选型广告。</span></p><p><span class="marginnote">直觉类比：无共享像每个店员有自己锁着的收银抽屉——账目清楚、互不干扰，但店员请假得交接钥匙（副本升主）；共享磁盘像全店共用一台收银机——换人顶班极快，可两人同时找零就得排队拿锁（DLM），高峰期队伍反而更长。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分析 MPP 常无共享+shuffle。OLTP 集群共享盘图省分片，但要买 DLM。云盘可被多挂，像共享盘，延迟与 IO 隔离是新问题——下一课分离。</p><p>分片键在无共享是必须；共享盘可先不分片。</p>',11)),(s(),n(i,null,{default:a(()=>[B(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SN%5B%22%E6%97%A0%E5%85%B1%E4%BA%AB%22%5D%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%E6%90%AC%E6%95%B0%E6%8D%AE%22%5D%0A%20%20SN%20--%3E%20REP%5B%22%E7%94%A8%E5%89%AF%E6%9C%AC%E6%8A%97%E8%8A%82%E7%82%B9%E6%95%85%E9%9A%9C%22%5D%0A%20%20SD%5B%22%E5%85%B1%E4%BA%AB%E7%A3%81%E7%9B%98%22%5D%20--%3E%20DLM%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E9%94%81%E4%B8%8E%E7%BC%93%E5%AD%98%E8%9E%8D%E5%90%88%22%5D%0A%20%20SD%20--%3E%20FAIL%5B%22%E8%AE%A1%E7%AE%97%E6%8D%A2%E6%9C%BA%E3%80%81%E7%9B%98%E4%BB%8D%E5%9C%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"代价模型：无共享连接计网络；共享盘计跨机页运。2Q 在共享盘要考虑被别的节点偷页。WAL：共享盘上日志设备也共享，组提交争用。",-1)),E[5]||(E[5]=e("p",null,"一致性哈希落在无共享上自然；共享盘用哈希分区仍可，但是可选。",-1)),(s(),n(i,null,{default:a(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E6%9F%90%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%E5%AE%95%E6%9C%BA%22%5D%20--%3E%20Q%7B%22%E5%93%AA%E7%A7%8D%E6%9E%B6%E6%9E%84%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%85%B1%E4%BA%AB%E7%A3%81%E7%9B%98%7C%20F%5B%22%E8%AE%A1%E7%AE%97%E5%88%87%E5%88%B0%E5%AD%98%E6%B4%BB%E8%8A%82%E7%82%B9%22%5D%0A%20%20F%20--%3E%20F2%5B%22%E7%9B%98%E4%BB%8D%E5%8F%AF%E8%BE%BE%2C%20%E9%87%8D%E5%BB%BA%E9%94%81%E4%B8%8E%E7%BC%93%E5%AD%98%E7%8A%B6%E6%80%81%22%5D%0A%20%20F2%20--%3E%20UP%5B%22%E8%BE%83%E5%BF%AB%E6%81%A2%E5%A4%8D%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20Q%20--%3E%7C%E6%97%A0%E5%85%B1%E4%BA%AB%7C%20R%5B%22%E6%89%BE%E5%88%B0%E8%AF%A5%E8%8A%82%E7%82%B9%E6%95%B0%E6%8D%AE%E7%9A%84%E5%89%AF%E6%9C%AC%22%5D%0A%20%20R%20--%3E%20R2%5B%22%E5%89%AF%E6%9C%AC%E5%8D%87%E4%B8%BB%20%2B%20%E6%9B%B4%E6%96%B0%E8%B7%AF%E7%94%B1%22%5D%0A%20%20R2%20--%3E%20UP2%5B%22%E6%81%A2%E5%A4%8D%E6%97%B6%E9%95%BF%E5%8F%96%E5%86%B3%E4%BA%8E%E5%89%AF%E6%9C%AC%E8%BF%BD%E8%B5%B6%E8%BF%9B%E5%BA%A6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">数字实例：共享盘上两个节点抢写同一热点页，每次都要跨机拿页锁、走 cache fusion 传页版本——一次跨机往返在数据中心内也要几十到上百微秒；无共享架构里这页只有主节点写，没有跨机协调，代价是热点收敛在单节点上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲存算分离的对象存储。也不把无共享当「无状态」。HTAP 可能一侧无共享列存。</p><p>后课默认：MPP 无共享；传统集群共享盘存在。存算分离：计算无状态、存储多租户服务化。</p><p>分类决定故障时搬计算还是搬数据。</p><p><span class="marginnote">常见误区：初学者容易把「无共享」读成「无状态」。恰恰相反——每个节点持有一份私有数据加副本，状态最重；无状态的是下一课存算分离里的计算层。nothing 指的是「不共享磁盘」，不是「什么都不共享」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无共享扩盘与计算绑定，靠副本；共享盘换计算快、写争用高。</li><li>连接与锁的代价项因此不同。</li><li>存算分离下一课。</li><li>出处：DeWitt and Gray；Stonebraker；RAC 实践。</li></ul>',8))])}const _=o(p,[["render",h]]);export{P as __pageData,_ as default};
